import { webkit } from 'playwright';

const R='abcdefghi';
const INIT='lnsgkgsnl/1r5b1/ppppppppp/9/9/9/PPPPPPPPP/1B5R1/LNSGKGSNL';
const MOVES=`4i5h 8c8d 2h3h 8d8e 6g6f 8e8f 8g8f 8b8f 7g7f 8f8g+ 6i7h 8g7f P*7b 7a7b 5i4i 7f8e 3i4h P*8f 6f6e 8f8g+ 8h5e 8e6e 7h6h 6e5e 5g5f 5e7e 6h6i 3c3d 9g9f 2b9i+ 7i8h 9i8h 3h3i B*2h 3i3h`.split(/\s+/);
function sfen(ms){const b=new Map(),h={b:{},w:{}};let rr=0;for(const row of INIT.split('/')){let f=9,pr=false;for(const c of row){if(c==='+'){pr=true;continue}if(/\d/.test(c)){f-=+c;continue}const side=c===c.toUpperCase()?'b':'w';b.set(''+f+R[rr],{side,k:c.toUpperCase(),pr});pr=false;f--}rr++}let t='b';for(const m of ms){if(/^[PLNSGBR]\*/.test(m)){const k=m[0],d=m.slice(2);h[t][k]=(h[t][k]||0)-1;b.set(d,{side:t,k,pr:false})}else{const a=m.slice(0,2),d=m.slice(2,4),p=m.endsWith('+'),pc=b.get(a);if(!pc)throw Error('missing '+a+' '+m);const cap=b.get(d);if(cap)h[t][cap.k]=(h[t][cap.k]||0)+1;b.delete(a);b.set(d,{...pc,pr:pc.pr||p})}t=t==='b'?'w':'b'}const rows=[];for(let r=0;r<9;r++){let x='',e=0;for(let f=9;f;f--){const pc=b.get(''+f+R[r]);if(!pc){e++;continue}if(e){x+=e;e=0}x+=(pc.pr?'+':'')+(pc.side==='b'?pc.k:pc.k.toLowerCase())}if(e)x+=e;rows.push(x)}let hand='';for(const side of['b','w'])for(const k of['R','B','G','S','N','L','P']){const n=h[side][k]||0;if(n>0)hand+=(n>1?n:'')+(side==='b'?k:k.toLowerCase())}return rows.join('/')+' '+t+' '+(hand||'-')+' '+(ms.length+1)}
const targets=[5,9,13,17,19,23,33,35].map(ply=>({ply,pos:sfen(MOVES.slice(0,ply-1))}));
const browser=await webkit.launch({headless:true});
async function makePage(ua){const page=await browser.newPage({userAgent:ua});await page.goto('http://127.0.0.1:4202/shogi-v21528/index.html?runtimeaudit='+Date.now(),{waitUntil:'domcontentloaded',timeout:120000});await page.waitForFunction(()=>document.querySelectorAll('#chars .ch').length===26,{timeout:120000});return page}
async function run(page,pos,{nodes=0,multiPV=1,ms=4000}={}){return page.evaluate(async({pos,nodes,multiPV,ms})=>{const w=new Worker('./future-yaneura-worker21528.js?v=runtimeaudit-'+Date.now());let id=0,P=new Map();w.onmessage=e=>{const m=e.data||{},q=P.get(m.id);if(!q||m.type!=='result')return;P.delete(m.id);clearTimeout(q.t);m.ok?q.r(m):q.j(Error(m.error||'worker'))};const call=(type,x={})=>new Promise((r,j)=>{const n=++id,t=setTimeout(()=>{P.delete(n);j(Error(type+' timeout'))},150000);P.set(n,{r,j,t});w.postMessage({type,id:n,...x})});try{await call('init');const started=Date.now(),r=await call('bestmove',{sfen:pos,ms,nodes,multiPV});return{...r,elapsed:Date.now()-started}}finally{w.terminate()}},{pos,nodes,multiPV,ms})}
try{
  const iphoneUA='Mozilla/5.0 (iPhone; CPU iPhone OS 18_6 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.6 Mobile/15E148 Safari/604.1';
  const page=await makePage(iphoneUA);let exact=0,triggered=0,total=0,elapsed=0;
  for(const t of targets){const ref=await run(page,t.pos,{nodes:8000000,multiPV:5,ms:4000});const refBest=(ref.candidates||[]).find(x=>x.rank===1)?.token||ref.token;console.log('RUNTIME_REF '+JSON.stringify({ply:t.ply,best:refBest,elapsed:ref.elapsed,threads:ref.info?.threads,hashMB:ref.info?.hashMB,mobileWebKit:ref.info?.mobileWebKit}));for(let rep=1;rep<=2;rep++){const r=await run(page,t.pos,{ms:4000,multiPV:1});const row={ply:t.ply,rep,refBest,token:r.token,exact:r.token===refBest,elapsed:r.elapsed,policy:r.info?.policy,policyStage:r.info?.policyStage,triggered:!!r.info?.policyTriggered,gapCp:r.info?.policyGapCp,thresholdCp:r.info?.policyThresholdCp,stage1Nodes:r.info?.stage1Nodes,stage2Nodes:r.info?.stage2Nodes,stageCandidates:r.info?.stageCandidates,threads:r.info?.threads,hashMB:r.info?.hashMB,mobileWebKit:r.info?.mobileWebKit,fireSilk:r.info?.fireSilk};exact+=row.exact?1:0;triggered+=row.triggered?1:0;elapsed+=row.elapsed;total++;console.log('RUNTIME_ROW '+JSON.stringify(row))}}
  console.log('RUNTIME_SUMMARY '+JSON.stringify({tests:total,exact,triggered,meanElapsed:Math.round(elapsed/total)}));
  await page.close();

  const fireUA='Mozilla/5.0 (Linux; U; en-US) AppleWebKit/535.19 (KHTML, like Gecko) Silk/125.4 like Chrome/125.0 Safari/535.19';
  const fire=await makePage(fireUA);for(const t of targets.filter(x=>x.ply===19||x.ply===35)){const r=await run(fire,t.pos,{ms:4000,multiPV:1});console.log('FIRE_ROW '+JSON.stringify({ply:t.ply,token:r.token,elapsed:r.elapsed,policy:r.info?.policy,policyStage:r.info?.policyStage,triggered:!!r.info?.policyTriggered,threads:r.info?.threads,hashMB:r.info?.hashMB,mobileSafe:r.info?.mobileSafe,fireSilk:r.info?.fireSilk}))}await fire.close();
}finally{await browser.close()}
